const headers = require('../lib/download-headers');

test('benign_control', () => {
  expect(headers.disposition('report.txt')).toBe('attachment; filename="report.txt"');
});

test('security_keeps_one_header_line', () => {
  const value = headers.disposition("report.txt\r\nSet-Cookie: session=x");
  expect(value).not.toMatch(/[\r\n]/);
});
